/* Data contract for the requirement pipeline (/dashboard/[market]/[series]).
 *
 * Two sources fill it:
 *  - web/data-local/pipeline.json: built from BMW's dataset by scripts/build-pipeline-data.py. Git-ignored, local only.
 *  - src/lib/pipeline/example.ts: example data with the same shape, used when the local file is missing (e.g. on Vercel).
 */
import type { MarketId } from "@/lib/markets";

export type SeriesId = "F70" | "G60" | "G70";
export type Category = "Exterior" | "Interior" | "Digital" | "Powertrain";
export const CATEGORIES: Category[] = ["Exterior", "Interior", "Digital", "Powertrain"];

/** Markets in the feedback data. "OTHER" = countries outside the four app markets (KR, AU, CA, ZA, …). */
export type DataMarket = MarketId | "OTHER";

export interface OptionItem {
  /** BMW option code, e.g. "337". */
  code: string;
  /** Name as printed in the option list (German). */
  name: string;
  /** Price in EUR incl. VAT; null when the list shows "–,–" (standard or included). */
  priceEur: number | null;
  /** Section heading in the option list. */
  group: string;
}

export interface FeatureRequest {
  id: string;
  series: SeriesId;
  /** Short, PM-friendly name, e.g. "Simpler iDrive menus". */
  title: string;
  category: Category;
  /** One sentence: what customers ask for. */
  summary: string;
  /** Unique feedback records behind this request. */
  mentions: number;
  /** Mentions per market (only markets with data). */
  byMarket: Partial<Record<DataMarket, number>>;
  /** How the mentions split by feedback type. */
  types: { wants: number; difficult: number; defect: number };
  /** Feedback channels behind it (anonymised source names from the dataset). */
  sources: { name: string; count: number }[];
  /** Up to 3 short customer quotes (local data only; empty in the example set). */
  quotes: string[];
  /** The BMW taxonomy topic(s) the cluster was built from, for traceability. */
  taxonomy: string[];
  /** Related options already on the price list today, if any. */
  relatedOptions: OptionItem[];
}

export interface SeriesData {
  id: SeriesId;
  /** "1 Series" etc. */
  name: string;
  /** Unique feedback records for this series, per market. */
  feedbackByMarket: Partial<Record<DataMarket, number>>;
  /** Clustered requests, sorted by mentions (desc). */
  requests: FeatureRequest[];
  /** What customers like most (for context on the profile pages). */
  strengths: { title: string; mentions: number }[];
  /** Customer-study scores per market (0–10 for CN/EU; US uses its own 1–7 scale and is converted ×10/7). */
  studies: { market: MarketId; attribute: string; score: number }[];
  /** Units per market and year (2030 is BMW's forecast). */
  sales: { market: MarketId | "ROW"; y2024: number | null; y2025: number | null; y2030: number | null }[];
  /** Option list (Germany, July 2026), trimmed to the useful items. */
  options: OptionItem[];
}

export interface PipelineData {
  /** "bmw" when built from the local dataset, "example" otherwise. */
  origin: "bmw" | "example";
  generatedAt: string;
  series: SeriesData[];
}

/** L2 market signal found by the research agent: a competitor feature people like, or a market trend. Public sources only. */
export interface MarketSignal {
  id: string;
  kind: "competitor" | "trend";
  series: SeriesId[];
  /** Official markets the signal applies to. */
  markets: ("EU" | "US" | "CN")[];
  /** ≤ 6 words. */
  title: string;
  /** Competitor model, for kind "competitor". */
  competitor?: string;
  category: Category;
  /** ≤ 20 words. */
  detail: string;
  /** Exact FeatureRequest titles this signal supports (customer feedback that asks for the same thing). */
  relatesTo: string[];
  strength: "strong" | "emerging";
  sources: { label: string; url: string }[];
}
/* Generations (stored as sessions): every "Build profiles" saves a snapshot, so a PM can reopen earlier generations later.
 * Stored in this browser for now (localStorage); moves to Supabase with the backend.
 */
import type { MarketScope } from "@/lib/dashboard-data";
import type { Campaign } from "./analytics";
import type { Decisions, Profile } from "./profiles";
import type { SeriesId } from "./types";

export interface Session {
  id: string;
  createdAt: string;
  scope: MarketScope;
  scopeLabel: string;
  series: SeriesId;
  seriesName: string;
  slug: string;
  profiles: Profile[];
  decisions: Decisions;
  order: string[];
  campaigns: Campaign[] | null;
}

const KEY = "dixi:sessions";
const MAX = 30;

export function readSessions(): Session[] {
  try {
    return (JSON.parse(localStorage.getItem(KEY) ?? "[]") as Session[]).sort((a, b) => b.createdAt.localeCompare(a.createdAt));
  } catch {
    return [];
  }
}

function write(list: Session[]) {
  try {
    localStorage.setItem(KEY, JSON.stringify(list.slice(0, MAX)));
  } catch {
    /* storage full or blocked: sessions stay for this visit only */
  }
}

export function saveSession(s: Session) {
  write([s, ...readSessions().filter((x) => x.id !== s.id)]);
}

export function updateSession(id: string, patch: Partial<Session>) {
  write(readSessions().map((s) => (s.id === id ? { ...s, ...patch } : s)));
}

export function deleteSession(id: string) {
  write(readSessions().filter((s) => s.id !== id));
}

export const newSessionId = () => `G-${Date.now().toString(36).toUpperCase()}`;

/** The generation's own dashboard. */
export const generationHref = (id: string) => `/dashboard/generations#${id}`;
/** Back into the pipeline with this generation's decisions and priority loaded, to edit and rebuild. */
export const editHref = (s: Pick<Session, "scope" | "slug" | "id">) => `/dashboard/${s.scope.toLowerCase()}/${s.slug}#session=${s.id}`;

export const sessionTime = (iso: string) => new Date(iso).toLocaleString("en-GB", { dateStyle: "medium", timeStyle: "short" });
/* Server-only loader: the local BMW-derived file when it exists, otherwise the example set.
 * readFileSync at module scope runs once and is prerendered (see Next docs: caching → predictable values).
 */
import fs from "node:fs";
import path from "node:path";
import { EXAMPLE_PIPELINE } from "./example";
import type { PipelineData, SeriesId } from "./types";

const LOCAL_FILE = path.join(process.cwd(), "data-local", "pipeline.json");

function load(): PipelineData {
  try {
    return JSON.parse(fs.readFileSync(LOCAL_FILE, "utf-8")) as PipelineData;
  } catch {
    return EXAMPLE_PIPELINE;
  }
}

const DATA = load();

export const pipelineOrigin = () => DATA.origin;
export const seriesData = (id: SeriesId) => DATA.series.find((s) => s.id === id) ?? EXAMPLE_PIPELINE.series.find((s) => s.id === id)!;
/* Per-series settings for the pipeline: URL slugs, L1 principles, competitors and the L3 weight.
 * Principles and competitor notes are example content written for the prototype (a PM would own and edit them);
